n\nAC1: wm-audio fetch-models --help implemented; AC2: --list --format json\npath wired; AC4: sha256 mismatch returns ModelError::Sha256Mismatch;\nAC5: is_current skips re-download; AC6: write_provenance + read_provenance\nround-trip; AC7: NeedsPrivilege exit-2 + sudo hint path.","tree":{"sha":"46e8f5bdaa7942b0eb94a7b595a366d23ebbde05","url":"https://api.github.com/repos/j0yen/wintermute-audio/git/trees/46e8f5bdaa7942b0eb94a7b595a366d23ebbde05"},"url":"https://api.github.com/repos/j0yen/wintermute-audio/git/commits/c658e90562ebc155bfcba7fddb379e8f78591a3b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178452872?v=4","events_url":"https://api.github.com/users/j0yen/events{/privacy}","followers_url":"https://api.github.com/users/j0yen/followers","following_url":"https://api.github.com/users/j0yen/following{/other_user}","gists_url":"https://api.github.com/users/j0yen/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/j0yen","id":178452872,"login":"j0yen","node_id":"U_kgDOCqL5iA","organizations_url":"https://api.github.com/users/j0yen/orgs","received_events_url":"https://api.github.com/users/j0yen/received_events","repos_url":"https://api.github.com/users/j0yen/repos","site_admin":false,"starred_url":"https://api.github.com/users/j0yen/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/j0yen/subscriptions","type":"User","url":"https://api.github.com/users/j0yen","user_view_type":"public"},"html_url":"https://github.com/j0yen/wintermute-audio/commit/c658e90562ebc155bfcba7fddb379e8f78591a3b","node_id":"C_kwDOSp3UndoAKGM2NThlOTA1NjJlYmMxNTViZmNiYTdmZGRiMzc5ZThmNzg1OTFhM2I","parents":[{"html_url":"https://github.com/j0yen/wintermute-audio/commit/dce203fde506f9d99c7187dcf02b51ff3ad39d5e","sha":"dce203fde506f9d99c7187dcf02b51ff3ad39d5e","url":"https://api.github.com/repos/j0yen/wintermute-audio/commits/dce203fde50